<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import api from '../services/api'
import type { Workshop } from '../types'
import { updateWorkshop } from '../services/workshops'
import SmartAddressFields from '../components/SmartAddressFields.vue'

type WorkshopRecord = Workshop & { id: number; is_active: boolean }
const list = ref<WorkshopRecord[]>([])
const search = ref('')
const status = ref('todos')
const loading = ref(false)
const details = ref<WorkshopRecord | null>(null)
const editing = ref<WorkshopRecord | null>(null)
const editForm = ref<WorkshopRecord | null>(null)
const editSaving = ref(false)
const editSuccessMessage = ref('')
const editPhotoError = ref('')
const editFileInput = ref<HTMLInputElement | null>(null)
const confirmDeactivate = ref<WorkshopRecord | null>(null)
const error = ref('')
const message = ref('')
const isCompact = ref(window.innerWidth <= 850)
const activeCount = computed(() => list.value.filter(item => item.is_active).length)
const inactiveCount = computed(() => list.value.length - activeCount.value)

async function load() {
  loading.value = true; error.value = ''
  try { list.value = (await api.get<WorkshopRecord[]>('/workshops', { params: { search: search.value, status_filter: status.value } })).data }
  catch (cause: any) { error.value = cause.response?.data?.detail || 'No fue posible consultar los talleres.' }
  finally { loading.value = false }
}
function formatDate(value?: string) { return value ? new Intl.DateTimeFormat('es-MX', { dateStyle: 'medium' }).format(new Date(value)) : 'Sin fecha' }
const editValid = computed(() => {
  const form = editForm.value
  return !!form && form.name.trim().length >= 3 && /^[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}$/.test(form.rfc.trim().toUpperCase()) && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.contact_email) && form.street_and_number.trim().length >= 4 && form.neighborhood.trim().length >= 2 && /^\d{5}$/.test(form.postal_code) && !!form.state && !!form.municipality && !editPhotoError.value
})
function openEdit(item: WorkshopRecord) { if (!item.is_active) { error.value = 'Este taller está inactivo. Actívalo para volver a modificar su información.'; return }; editPhotoError.value = ''; editForm.value = { ...item }; editing.value = item; details.value = null }
function cancelEdit() { editing.value = null; editForm.value = null; editPhotoError.value = ''; if (editFileInput.value) editFileInput.value.value = '' }
function handleEditRfc(value: string) { if (editForm.value) editForm.value.rfc = value.toUpperCase().replace(/[^A-Z0-9Ñ&]/g, '').slice(0, 13) }
function selectEditPhoto(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; editPhotoError.value = ''; if (!file || !editForm.value) return; if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { editPhotoError.value = 'Usa una imagen JPG, PNG o WebP.'; return }; if (file.size > 15 * 1024 * 1024) { editPhotoError.value = 'La fotografía no puede superar 15 MB.'; return }; const reader = new FileReader(); reader.onload = loadEvent => { if (editForm.value) editForm.value.photo_url = loadEvent.target?.result as string }; reader.readAsDataURL(file) }
function removeEditPhoto() { if (editForm.value) editForm.value.photo_url = null; if (editFileInput.value) editFileInput.value.value = '' }
async function saveEdit() { if (!editForm.value || !editing.value) return; if (!editValid.value) { error.value = 'Revisa los campos obligatorios antes de guardar los cambios.'; return }; editSaving.value = true; error.value = ''; try { await updateWorkshop(editing.value.id, { ...editForm.value, name: editForm.value.name.trim(), rfc: editForm.value.rfc.trim().toUpperCase(), contact_email: editForm.value.contact_email.trim().toLowerCase(), street_and_number: editForm.value.street_and_number.trim(), neighborhood: editForm.value.neighborhood.trim(), postal_code: editForm.value.postal_code.trim(), state: editForm.value.state.trim(), municipality: editForm.value.municipality.trim() }); await load(); cancelEdit(); editSuccessMessage.value = 'Los cambios se guardaron correctamente.' } catch (cause: any) { error.value = cause.response?.data?.detail || 'No fue posible actualizar el taller.' } finally { editSaving.value = false } }
async function deactivate() {
  if (!confirmDeactivate.value) return
  try {
    await api.patch(`/workshops/${confirmDeactivate.value.id}/status`)
    message.value = 'El taller fue desactivado sin eliminar su historial.'
    confirmDeactivate.value = null
    await load()
  } catch (cause: any) { error.value = cause.response?.data?.detail || 'No fue posible desactivar el taller.' }
}
watch([search, status], load)
onMounted(() => { window.addEventListener('resize', () => { isCompact.value = window.innerWidth <= 850 }); load() })
</script>

<template>
  <v-container class="page-shell workshops-admin">
    <header class="page-header"><p class="eyebrow">CENTROS DE SERVICIO</p><div class="header-row"><div class="header-icon"><v-icon icon="mdi-storefront-check-outline" size="27" /></div><div><h1>Administración de talleres</h1><p class="subtitle">Consulta los establecimientos registrados y su información operativa.</p></div></div></header>
    <v-alert v-if="error" type="error" variant="tonal" closable class="mb-5" @click:close="error=''">{{ error }}</v-alert>
    <section class="metrics"><v-card class="metric" elevation="0"><div class="metric-icon blue"><v-icon icon="mdi-storefront-outline" /></div><strong>{{ list.length }}</strong><span>Talleres registrados</span></v-card><v-card class="metric" elevation="0"><div class="metric-icon green"><v-icon icon="mdi-check-circle-outline" /></div><strong>{{ activeCount }}</strong><span>Talleres activos</span></v-card><v-card class="metric" elevation="0"><div class="metric-icon amber"><v-icon icon="mdi-storefront-remove-outline" /></div><strong>{{ inactiveCount }}</strong><span>Talleres inactivos</span></v-card></section>
    <v-card class="module-card" elevation="0"><div class="table-heading"><div><h2>Centros automotrices registrados</h2><p>Busca por nombre, RFC, contacto o ubicación.</p></div></div><v-divider />
      <v-card-text class="filter-row"><v-text-field v-model="search" label="Buscar talleres" prepend-inner-icon="mdi-magnify" variant="outlined" density="comfortable" hide-details clearable /><v-select v-model="status" label="Estado" :items="[{title:'Todos los estados',value:'todos'},{title:'Activos',value:'activos'},{title:'Inactivos',value:'inactivos'}]" variant="outlined" density="comfortable" hide-details /></v-card-text>
      <div v-if="!isCompact" class="desktop-table"><v-table class="workshop-table" hover><thead><tr><th>Taller</th><th>RFC</th><th>Contacto</th><th>Ubicación</th><th>Estado</th><th class="text-right">Acciones</th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="empty-row"><v-progress-circular indeterminate color="primary" size="24" /> Cargando talleres…</td></tr><tr v-else-if="!list.length"><td colspan="6" class="empty-row"><v-icon icon="mdi-storefront-remove-outline" size="26" /> No se encontraron talleres con esos filtros.</td></tr><tr v-for="item in list" :key="item.id"><td><div class="workshop-name"><v-avatar color="primary" variant="tonal" size="38"><v-icon icon="mdi-storefront-outline" /></v-avatar><div><strong>{{ item.name }}</strong><small>Registrado {{ formatDate(item.created_at) }}</small></div></div></td><td><span class="rfc">{{ item.rfc }}</span></td><td><div class="contact"><v-icon icon="mdi-email-outline" size="16" /><span>{{ item.contact_email }}</span></div></td><td><div class="location"><v-icon icon="mdi-map-marker-outline" size="16" /><div><strong>{{ item.municipality }}, {{ item.state }}</strong><small>CP {{ item.postal_code }}</small></div></div></td><td><v-chip :color="item.is_active ? 'success' : 'grey'" size="small" variant="tonal"><v-icon start size="14" :icon="item.is_active ? 'mdi-check-circle' : 'mdi-pause-circle'" />{{ item.is_active ? 'Activo' : 'Inactivo' }}</v-chip></td><td><div class="actions"><v-tooltip text="Ver ficha"><template #activator="{ props }"><v-btn v-bind="props" :aria-label="`Ver detalle de ${item.name}`" icon="mdi-eye-outline" size="small" color="primary" variant="tonal" @click="details=item" /></template></v-tooltip><v-tooltip text="Editar taller"><template #activator="{ props }"><v-btn v-bind="props" :aria-label="`Editar ${item.name}`" icon="mdi-pencil-outline" size="small" color="primary" variant="tonal" @click="openEdit(item)" /></template></v-tooltip><v-tooltip text="Desactivar"><template #activator="{ props }"><v-btn v-bind="props" :aria-label="`Desactivar ${item.name}`" icon="mdi-storefront-remove-outline" size="small" color="error" variant="tonal" :disabled="!item.is_active" @click="confirmDeactivate=item" /></template></v-tooltip></div></td></tr></tbody></v-table></div>
      <div v-else class="mobile-list"><div v-if="loading" class="empty-row"><v-progress-circular indeterminate color="primary" size="24" /> Cargando talleres…</div><div v-else-if="!list.length" class="empty-row"><v-icon icon="mdi-storefront-remove-outline" size="26" /> No se encontraron talleres con esos filtros.</div><v-card v-for="item in list" :key="item.id" class="workshop-mobile" elevation="0"><div class="mobile-head"><v-avatar color="primary" variant="tonal" size="42"><v-icon icon="mdi-storefront-outline" /></v-avatar><div class="grow"><strong>{{ item.name }}</strong><span>{{ item.rfc }}</span></div><v-chip :color="item.is_active ? 'success' : 'grey'" size="x-small" variant="tonal">{{ item.is_active ? 'Activo' : 'Inactivo' }}</v-chip></div><p><v-icon icon="mdi-email-outline" /> {{ item.contact_email }}</p><p><v-icon icon="mdi-map-marker-outline" /> {{ item.municipality }}, {{ item.state }} · CP {{ item.postal_code }}</p><div class="mobile-actions"><small>Registrado {{ formatDate(item.created_at) }}</small><v-spacer /><v-btn :aria-label="`Ver detalle de ${item.name}`" icon="mdi-eye-outline" size="small" color="primary" variant="tonal" @click="details=item" /><v-btn :aria-label="`Editar ${item.name}`" icon="mdi-pencil-outline" size="small" color="primary" variant="tonal" @click="openEdit(item)" /><v-btn :aria-label="`Desactivar ${item.name}`" icon="mdi-storefront-remove-outline" size="small" color="error" variant="tonal" :disabled="!item.is_active" @click="confirmDeactivate=item" /></div></v-card></div>
    </v-card>
    <v-dialog :model-value="!!details" max-width="900" scrollable persistent class="workshop-details-dialog"><v-card class="dialog-card workshop-details"><header class="workshop-details__header"><div class="workshop-details__icon"><v-icon icon="mdi-storefront-outline" size="27" /></div><span class="workshop-details__divider" aria-hidden="true" /><div class="grow"><p class="eyebrow">FICHA DEL TALLER</p><h2>{{ details?.name }}</h2><p class="workshop-rfc"><v-icon icon="mdi-card-account-details-outline" size="16" /> RFC {{ details?.rfc }}</p></div><v-btn class="workshop-details__close" aria-label="Cerrar ficha" icon="mdi-close" variant="text" @click="details=null" /></header><v-card-text class="details-content"><div class="details-grid"><section class="photo-section"><v-img v-if="details?.photo_url" :src="details.photo_url" :alt="`Fotografía de ${details.name}`" height="380" cover class="workshop-photo"><template #placeholder><div class="photo-placeholder"><v-progress-circular indeterminate color="primary" /></div></template></v-img><div v-else class="no-photo"><v-icon icon="mdi-image-off-outline" size="32" /><span>Este taller no tiene fotografía registrada.</span></div></section><section class="info-section"><div class="section-title workshop-section-title"><div class="workshop-section-title__icon"><v-icon icon="mdi-information-outline" /></div><div><h3>Información de contacto</h3><p>Datos principales del establecimiento.</p></div></div><div class="info-card"><span>Correo de contacto</span><strong><v-icon icon="mdi-email-outline" size="18" /> {{ details?.contact_email }}</strong></div><div class="section-title workshop-section-title address-title"><div class="workshop-section-title__icon"><v-icon icon="mdi-map-marker-outline" /></div><div><h3>Domicilio</h3><p>Ubicación registrada para el centro automotriz.</p></div></div><div class="address-card"><strong>{{ details?.street_and_number }}</strong><span>{{ details?.neighborhood }}</span><span>{{ details?.municipality }}, {{ details?.state }}</span><div class="postal-band"><v-icon icon="mdi-map-marker" size="16" />CP {{ details?.postal_code }}</div></div><div class="status-row"><div class="operational-status" :class="details?.is_active ? 'operational-status--active' : 'operational-status--inactive'"><span>Estado operativo</span><strong><v-icon :icon="details?.is_active ? 'mdi-check-circle' : 'mdi-pause-circle'" size="20" />{{ details?.is_active ? 'Activo' : 'Inactivo' }}</strong></div><div class="registration-date"><span><v-icon icon="mdi-calendar-outline" size="18" />Fecha de registro</span><strong>{{ formatDate(details?.created_at) }}</strong></div></div></section></div></v-card-text><v-card-actions class="dialog-actions workshop-details__actions"><v-spacer /><v-btn class="workshop-close-button" variant="outlined" prepend-icon="mdi-close" @click="details=null">Cerrar detalle</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!editing" max-width="820" scrollable persistent>
      <v-card v-if="editForm" class="dialog-card workshop-edit-dialog">
        <div class="dialog-heading workshop-edit-dialog__header"><div class="header-icon"><v-icon icon="mdi-pencil-outline" size="25" /></div><div><h2>Editar taller</h2><p>Actualiza los datos operativos del establecimiento. La fecha de registro se conserva.</p></div></div>
        <v-card-text class="workshop-edit-dialog__content">
          <div class="workshop-edit-grid">
            <v-text-field v-model.trim="editForm.name" label="Nombre del taller *" prepend-inner-icon="mdi-storefront-outline" variant="outlined" density="comfortable" :rules="[v => !!v || 'El nombre es obligatorio.']" />
            <v-text-field :model-value="editForm.rfc" label="RFC *" prepend-inner-icon="mdi-card-account-details-outline" variant="outlined" density="comfortable" maxlength="13" :rules="[v => !!v || 'El RFC es obligatorio.']" @update:model-value="handleEditRfc" />
            <v-text-field v-model.trim="editForm.contact_email" label="Correo de contacto *" prepend-inner-icon="mdi-email-outline" type="email" variant="outlined" density="comfortable" />
            <div class="operational-state-field"><v-select v-model="editForm.is_active" label="Estado operativo" aria-label="Estado operativo" :items="[{ title: 'Activo', value: true }, { title: 'Inactivo', value: false }]" :class="editForm.is_active ? 'operational-field--active' : 'operational-field--inactive'" :prepend-inner-icon="editForm.is_active ? 'mdi-check' : 'mdi-pause'" variant="outlined" density="comfortable" hide-details /></div>
            <section class="workshop-edit-date"><v-icon icon="mdi-calendar-lock-outline" size="23" /><div><span>Fecha de registro</span><strong>{{ formatDate(editForm.created_at) }}</strong></div><v-divider vertical /><p>Dato histórico no modificable.</p></section>
          </div>
          <section class="workshop-edit-address"><div class="workshop-edit-section-title"><div><v-icon icon="mdi-map-marker-outline" /></div><div><h3>Dirección</h3><p>Información de contacto y ubicación del establecimiento.</p></div><span>Campos obligatorios *</span></div><v-row><v-col cols="12" md="6"><v-text-field v-model.trim="editForm.street_and_number" label="Calle y número *" prepend-inner-icon="mdi-road-variant" variant="outlined" density="comfortable" /></v-col></v-row><SmartAddressFields :show-icons="true" v-model:state="editForm.state" v-model:municipality="editForm.municipality" v-model:neighborhood="editForm.neighborhood" v-model:postal-code="editForm.postal_code" /></section>
          <section class="workshop-edit-photo"><div><strong>Fotografía del taller</strong><span>JPG, PNG o WebP; máximo 15 MB.</span></div><input ref="editFileInput" class="d-none" type="file" accept="image/jpeg,image/png,image/webp" @change="selectEditPhoto" /><div v-if="editForm.photo_url" class="workshop-edit-photo__media"><v-img :src="editForm.photo_url" class="workshop-edit-photo__preview" cover /><div class="workshop-edit-photo__overlay"><v-btn size="small" variant="flat" prepend-icon="mdi-image-edit-outline" @click="editFileInput?.click()">Cambiar foto</v-btn><v-btn size="small" variant="flat" color="error" prepend-icon="mdi-delete-outline" @click="removeEditPhoto">Eliminar foto</v-btn></div></div><button v-else type="button" class="workshop-edit-photo__empty" @click="editFileInput?.click()"><v-icon icon="mdi-image-plus-outline" size="30" /><strong>Cambiar fotografía</strong></button><p v-if="editPhotoError" class="text-error mt-2">{{ editPhotoError }}</p></section>
        </v-card-text>
        <v-card-actions class="dialog-actions workshop-edit-dialog__actions"><v-spacer /><v-btn class="workshop-close-button" variant="outlined" prepend-icon="mdi-close" :disabled="editSaving" @click="cancelEdit">Cancelar</v-btn><v-btn class="workshop-save-button" color="primary" variant="flat" prepend-icon="mdi-content-save-outline" :loading="editSaving" :disabled="editSaving" @click="saveEdit">Guardar cambios</v-btn></v-card-actions>
      </v-card>
    </v-dialog>
    <v-dialog :model-value="!!confirmDeactivate" max-width="480" persistent><v-card class="dialog-card workshop-deactivate-dialog"><header class="workshop-deactivate-dialog__header"><div class="workshop-deactivate-dialog__header-icon"><v-icon icon="mdi-storefront-outline" size="25" /></div><div><h2>Desactivar taller</h2><p>Acción de baja administrativa.</p></div></header><v-card-text class="workshop-deactivate-dialog__content"><v-icon class="workshop-deactivate-dialog__warning" icon="mdi-alert-circle-outline" size="62" /><h3>¿Seguro que deseas <span>dar de baja</span> este taller?</h3><p><strong>{{ confirmDeactivate?.name }}</strong></p><p class="workshop-deactivate-dialog__helper">Se conservará todo su historial y, antes de continuar, verificaremos que no tenga vehículos registrados.</p></v-card-text><v-card-actions class="dialog-actions workshop-deactivate-dialog__actions"><v-spacer /><v-btn class="workshop-deactivate-dialog__cancel" variant="outlined" prepend-icon="mdi-close" @click="confirmDeactivate=null">Cancelar</v-btn><v-btn class="workshop-deactivate-dialog__confirm" prepend-icon="mdi-storefront-remove-outline" @click="deactivate">Desactivar</v-btn></v-card-actions></v-card></v-dialog>
    <v-snackbar :model-value="!!message" color="success" timeout="4000" location="top right" class="workshop-success" @update:model-value="message=''"><v-icon icon="mdi-check-circle" class="mr-2" />{{ message }}</v-snackbar>
    <v-snackbar :model-value="!!editSuccessMessage" timeout="1000" location="bottom" class="workshop-edit-success-snackbar" @update:model-value="editSuccessMessage=''"><v-icon icon="mdi-check-circle" class="mr-2" />{{ editSuccessMessage }}</v-snackbar>
  </v-container>
</template>

